import React, { useEffect, useMemo, useState } from 'react';
import { Activity, ArrowDownToLine, ArrowLeft, ArrowRight, Bell, ChevronDown, CircleHelp, Clock3, Command, Globe, Hammer, Image, LayoutDashboard, Link, LogOut, Menu, MoreHorizontal, Play, Plus, Search, Settings, ShieldCheck, Share2, Trophy, Tv, Users, UserRound, Volume2, Wallet, X, Zap } from 'lucide-react';
import playerData from './playerData.json';

const initialTeams = [
  { name: 'Team 1', short: 'T1', color: '#244bbd', purse: 90000, spent: 0, players: 0 },
  { name: 'Team 2', short: 'T2', color: '#d12c2c', purse: 90000, spent: 0, players: 0 },
  { name: 'Team 3', short: 'T3', color: '#edb200', purse: 90000, spent: 0, players: 0 },
  { name: 'Team 4', short: 'T4', color: '#6b269a', purse: 90000, spent: 0, players: 0 },
];
const CONFIG_KEY = 'gnpl_auction_settings';
const PLAYER_POOL_KEY = 'gnpl_auction_player_pool';
const defaultAuctionSettings = { bidIncrement: 1000, teamPurse: 90000, maxPlayers: 9, timerSeconds: 30, autoSold: false, voice: true, paddle: true, retentions: true, maxRetentions: 3 };
const readAuctionSettings = () => { try { return { ...defaultAuctionSettings, ...JSON.parse(localStorage.getItem(CONFIG_KEY) || '{}') }; } catch { return defaultAuctionSettings; } };
const mapGnplRoster = rows => rows.map((player, index) => ({
  sourceId: player.id,
  lot: index + 1,
  name: player.name,
  category: ['A+', 'A', 'B'].includes(player.grade) ? player.grade : 'B',
  role: player.role || 'Player',
  age: player.age || null,
  experience: player.experience || null,
  batting: player.batting || '',
  bowling: player.bowling || '',
  matches: player.matches || 0,
  runs: player.runs || 0,
  wickets: player.wickets || 0,
  playerNumber: player.playerNumber || '',
  photo: player.photo || null,
  basePrice: player.basePrice || 1000,
  status: 'Available', soldPrice: null, team: 'Unassigned',
}));
const mergePlayerStates = (roster, saved = []) => roster.map(player => {
  const previous = saved.find(item => (player.sourceId && item.sourceId === player.sourceId) || item.name?.trim().toLowerCase() === player.name.trim().toLowerCase());
  return previous ? { ...player, status: previous.status || 'Available', soldPrice: previous.soldPrice ?? null, team: previous.team || 'Unassigned' } : player;
});
const initialPlayers = [
  { name: 'Arjun Rao', role: 'All-rounder', category: 'A', base: 25000, bid: 78000, team: 'Mumbai Strikers', status: 'In auction', initials: 'AR', color: '#d8ae88' },
  { name: 'Rohit Deshmukh', role: 'Batter', category: 'A', base: 20000, bid: 65000, team: 'North Knights', status: 'Sold', initials: 'RD', color: '#c59b85' },
  { name: 'Ishan Patel', role: 'Bowler', category: 'B', base: 15000, bid: 45000, team: 'Pune Panthers', status: 'Sold', initials: 'IP', color: '#aab7a4' },
  { name: 'Kabir Nair', role: 'Wicketkeeper', category: 'A', base: 30000, bid: 0, team: '', status: 'Upcoming', initials: 'KN', color: '#b89f8c' },
  { name: 'Dev Shah', role: 'Batter', category: 'B', base: 10000, bid: 0, team: '', status: 'Unsold', initials: 'DS', color: '#d1aa83' },
  { name: 'Aman Kulkarni', role: 'Bowler', category: 'C', base: 10000, bid: 0, team: '', status: 'Upcoming', initials: 'AK', color: '#aeb5a5' },
];
const money = n => `₹${new Intl.NumberFormat('en-IN').format(n)}`;

function TournamentManagement({ onGoAuction, onOpenTeams, onOpenPlayers, onOpenConfiguration, notice, playerCount }) {
  const [search,setSearch]=useState('');
  const [configOpen,setConfigOpen]=useState(false);
  const [rowsPerPage,setRowsPerPage]=useState('50');
  const [createOpen,setCreateOpen]=useState(false);
  const matches='Godrej Nest Cricket League'.toLowerCase().includes(search.trim().toLowerCase());
  return <div className="pb-tournament-page"><div className="pb-tournament-page-head"><h1>Tournament Management</h1><div><button className="pb-slot-button" onClick={()=>notice('Tournament slot options are not connected in this preview.')}>＋ Get More Slots</button><span className="pb-limit-label">TOURNAMENT LIMIT: <b>1 Used | 0 Remaining</b></span><button className="pb-create-button" onClick={()=>setCreateOpen(true)}>＋ Create Tournament</button></div></div><label className="pb-tournament-search"><Search size={15}/><input value={search} onChange={event=>setSearch(event.target.value)} placeholder="Search tournaments by name, email, phone..." /></label>
    {matches&&<article className="pb-tournament-card"><div className="pb-tournament-card-head"><span className="pb-trophy-tile"><Trophy size={20}/></span><div className="pb-tournament-title"><b>Godrej Nest Cricket League</b><span><i>GNPL 2026</i><small>TENNISBALL</small></span></div><span className="pb-selected-label">SELECTED</span><span className="pb-tourney-live"><i/> AUCTION SCHEDULED</span></div><div className="pb-tournament-meta"><div><b>Sat, 21 Nov · 7:00 PM</b><small>7TH FLOOR PODIUM</small></div><div><b>4</b><small>TEAMS</small></div><div><b>{playerCount}</b><small>PLAYERS</small></div></div><div className="pb-tournament-actions"><div className="pb-config-wrap"><button className="pb-create-button" onClick={()=>setConfigOpen(!configOpen)}><Settings size={13}/> Configure⌄</button>{configOpen&&<div className="pb-config-menu">{['Tournament settings','Auction rules','Registration form'].map(item=><button key={item} onClick={()=>{setConfigOpen(false);onOpenConfiguration(item);}}>{item}</button>)}</div>}</div><button onClick={onOpenTeams}>♙ Teams</button><button onClick={onOpenPlayers}>♙ Players</button><button className="pb-create-button" onClick={onGoAuction}><Hammer size={13}/> Go to Auction</button><button onClick={()=>notice('Tournament links copied.')}>⌁ Links</button></div></article>}
    {!matches&&<div className="pb-tournaments-empty">No tournaments match “{search}”.</div>}
    <footer className="pb-tournament-pagination"><span>Showing <b>{matches?1:0} to {matches?1:0}</b> of {matches?1:0} tournaments</span><div><button disabled>‹</button><b>1</b><button disabled>›</button></div><label>Show: <select value={rowsPerPage} onChange={event=>setRowsPerPage(event.target.value)}><option>10</option><option>25</option><option>50</option><option>100</option></select></label></footer>
    {createOpen&&<div className="pb-dialog-back" onMouseDown={event=>event.target===event.currentTarget&&setCreateOpen(false)}><form onSubmit={event=>{event.preventDefault();setCreateOpen(false);notice('Tournament creation is not connected in this preview.')}}><button type="button" className="pb-dialog-close" onClick={()=>setCreateOpen(false)}><X size={17}/></button><small>TOURNAMENT SETUP</small><h3>Create Tournament</h3><label>Name<input required placeholder="Tournament name"/></label><label>Sport<select defaultValue="TennisBall"><option>TennisBall</option><option>Cricket</option></select></label><button className="pb-dialog-action">Create</button></form></div>}
  </div>;
}

function AuctionReportDetails({ teamResults, completedLots }) {
  return <div className="pb-report-live-grid">
    <section className="pb-report-panel"><h2>Live squad standings</h2><div className="pb-report-table-wrap"><table className="pb-report-table"><thead><tr><th>TEAM</th><th>SQUAD</th><th>SPENT</th><th>BALANCE</th><th>RUNS / WKTS</th></tr></thead><tbody>{teamResults.map(team=><tr key={team.short}><td><b><i style={{'--team':team.color}}>{team.short}</i>{team.name}</b></td><td>{team.squad.length}</td><td>{money(team.spent)}</td><td>{money(team.balance)}</td><td>{team.runs} / {team.wickets}</td></tr>)}</tbody></table></div></section>
    <section className="pb-report-panel"><h2>Completed lots <span className="pb-count-badge">LIVE LEDGER</span></h2>{completedLots.length?<div className="pb-completed-lots">{completedLots.slice(0,8).map(lot=><article key={lot.id}><span>#{lot.lot}</span><b>{lot.player}</b><small>{lot.action==='Sold'?`Sold to ${lot.team}`:'Unsold'}</small><strong>{lot.action==='Sold'?money(lot.amount):'—'}</strong></article>)}</div>:<p className="pb-report-empty">Completed sales and unsold lots will appear here as the auction runs.</p>}</section>
  </div>;
}

function AuctionWorkspacePage({ section, playerPool, setPlayerPool, notice, onNavigate, sharedState, setSharedAuction }) {
  const [query, setQuery] = useState('');
  const [category, setCategory] = useState('All');
  const [expandedTeam, setExpandedTeam] = useState('');
  const [settings, setSettings] = useState(() => sharedState?.settings || readAuctionSettings());
  useEffect(() => { try { localStorage.setItem(PLAYER_POOL_KEY, JSON.stringify(playerPool)); } catch {} }, [playerPool]);
  useEffect(() => { try { localStorage.setItem(CONFIG_KEY, JSON.stringify(settings)); } catch {} setSharedAuction(previous => ({ ...previous, settings })); }, [settings]);
  useEffect(() => { if (sharedState?.settings && JSON.stringify(sharedState.settings) !== JSON.stringify(settings)) setSettings(sharedState.settings); }, [sharedState?.settings]);
  const teams = initialTeams.map(team => ({ ...team, purse: settings.teamPurse }));
  const updateSetting = (key, value) => setSettings(current => ({ ...current, [key]: value }));
  const filteredPlayers = playerPool.filter(player => `${player.name} ${player.role} ${player.category} ${player.status} ${player.team}`.toLowerCase().includes(query.toLowerCase()) && (category === 'All' || player.category === category));
  const setPlayerTeam = (player, teamName) => { if (teamName && teamName !== 'Unassigned') { const teamCount = playerPool.filter(item => item.team === teamName && item.status !== 'Unsold').length; if (player.team !== teamName && teamCount >= settings.maxPlayers) { notice(`${teamName} has reached its squad limit.`); return; } } setPlayerPool(current => current.map(item => item.lot === player.lot ? { ...item, team: teamName || 'Unassigned' } : item)); };

  if (section === 'Home') return <section className="pb-workspace-page">
    <div className="pb-workspace-heading"><div><span className="pb-workspace-eyebrow">ORGANIZER WORKSPACE / GNPL 2026</span><h1>Godrej Nest Cricket League</h1><p>Your tournament overview and quick access to auction tools.</p></div><span className="pb-workspace-count">AUCTION SCHEDULED</span></div>
    <div className="pb-report-stats"><article><small>REGISTERED TEAMS</small><b>4 / 6</b></article><article><small>PLAYER POOL</small><b>{playerPool.length}</b></article><article><small>AVAILABLE LOTS</small><b>{playerPool.filter(player=>player.status==='Available').length}</b></article><article><small>PLAYERS SOLD</small><b>{playerPool.filter(player=>player.status==='Sold').length}</b></article></div>
    <div className="pb-home-event"><span><Trophy size={20}/></span><div><small>NEXT EVENT</small><h2>Player auction</h2><p>Saturday, 21 November · 7:00 PM · 7th Floor Podium</p></div><button className="pb-workspace-primary" onClick={()=>onNavigate('Auction')}>Open auction arena <ArrowRight size={15}/></button></div>
    <div className="pb-home-shortcuts">{[['Teams','Manage team squads'],['Players','Browse the imported player pool'],['Configuration','Set purse, timer and auction rules'],['Reports','Review and export auction results']].map(([name,description])=><button key={name} onClick={()=>onNavigate(name)}><b>{name}</b><small>{description}</small><ArrowRight size={15}/></button>)}</div>
  </section>;

  if (section === 'Teams') return <section className="pb-workspace-page">
    <div className="pb-workspace-heading"><div><span className="pb-workspace-eyebrow">GODREJ NEST CRICKET LEAGUE / TOURNAMENT</span><h1>Teams &amp; squads</h1><p>Manage each franchise, purse balance, roster and retained players.</p></div><button className="pb-workspace-primary" onClick={() => notice('All four registered teams are listed below.')}>4 registered teams</button></div>
    <div className="pb-team-grid">{teams.map((team, index) => {
      const squad = playerPool.filter(player => player.team === team.name && player.status !== 'Unsold');
      const retainedSpend = squad.filter(player => ['Sold','Retained'].includes(player.status)).reduce((total,player) => total + Number(player.soldPrice || player.basePrice || 0), 0);
      const balance = Math.max(0, team.purse - retainedSpend);
      const expanded = expandedTeam === team.name;
      return <article className={`pb-team-card${expanded ? ' expanded' : ''}`} key={team.short} style={{ '--team': team.color }}>
        <header><span className="pb-team-emblem">{team.short}</span><div><h2>{team.name}</h2><small>{index < 4 ? 'REGISTERED FRANCHISE' : 'FRANCHISE'}</small></div><button aria-expanded={expanded} onClick={() => setExpandedTeam(expanded ? '' : team.name)}>{expanded ? 'Hide squad' : 'View squad'} <ChevronDown size={14}/></button></header>
        <div className="pb-team-stats"><div><small>PURSE BALANCE</small><b>{money(balance)}</b></div><div><small>SQUAD</small><b>{squad.length} / {settings.maxPlayers}</b></div><div><small>PLAYERS RETAINED</small><b>{squad.filter(player => player.status === 'Retained').length}</b></div><div><small>SQUAD RUNS / WKTS</small><b>{squad.reduce((sum,player)=>sum+Number(player.runs||0),0)} / {squad.reduce((sum,player)=>sum+Number(player.wickets||0),0)}</b></div></div>
        {expanded && <div className="pb-team-squad"><div className="pb-team-squad-head"><b>Team squad</b><span>{squad.length} players</span></div>{squad.length ? squad.map(player => <div className="pb-team-player" key={player.lot}><span>#{player.lot}</span><b>{player.name}</b><i>{player.category}</i><small>{player.status}</small></div>) : <p>No players assigned yet. Retain players here or assign them from the Players page.</p>}
          <label>Retain an available player<select defaultValue="" disabled={!settings.retentions || squad.length >= settings.maxPlayers || squad.filter(player => player.status === 'Retained').length >= settings.maxRetentions} onChange={event => { const lot = event.target.value; event.target.value = ""; const player = playerPool.find(item => String(item.lot) === lot); if (!player) return; if (!settings.retentions) { notice("Player retentions are disabled in Configuration."); return; } if (squad.length >= settings.maxPlayers || squad.filter(item => item.status === 'Retained').length >= settings.maxRetentions) { notice("This team has reached its retention or squad limit."); return; } setPlayerPool(current => current.map(item => item.lot === player.lot ? { ...item, team: team.name, status: 'Retained' } : item)); }}><option value="" disabled>{settings.retentions ? "Choose player to retain" : "Retentions disabled"}</option>{playerPool.filter(player => player.status === 'Available').map(player => <option key={player.lot} value={player.lot}>{player.name} · {player.category}</option>)}</select></label>
        </div>}
      </article>;
    })}</div>
    <div className="pb-workspace-note"><ShieldCheck size={17}/> Team changes sync to the live auction workspace.</div>
  </section>;

  if (section === 'Players') return <section className="pb-workspace-page">
    <div className="pb-workspace-heading"><div><span className="pb-workspace-eyebrow">GODREJ NEST CRICKET LEAGUE / TOURNAMENT</span><h1>Player pool</h1><p>Search imported registrations, review categories and manage auction status.</p></div><span className="pb-workspace-count">{playerPool.length} PLAYERS</span></div>
    <div className="pb-workspace-toolbar"><label className="pb-workspace-search"><Search size={17}/><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Search player, role or status" /></label><label className="pb-workspace-select">Category<select value={category} onChange={event => setCategory(event.target.value)}><option>All</option><option>A+</option><option>A</option><option>B</option></select></label><button className="pb-workspace-secondary" onClick={() => { setQuery(''); setCategory('All'); }}>Clear filters</button></div>
    <div className="pb-workspace-table-wrap"><table className="pb-workspace-table"><thead><tr><th>LOT</th><th>PLAYER</th><th>ROLE</th><th>CATEGORY</th><th>AGE</th><th>EXPERIENCE</th><th>BASE PRICE</th><th>STATUS</th><th>TEAM</th></tr></thead><tbody>{filteredPlayers.map(player => <tr key={player.sourceId || player.lot}><td>#{player.lot}</td><td><strong className="pb-player-name-cell">{player.photo&&<img src={player.photo} alt="" loading="lazy"/>}{player.name}</strong></td><td>{player.role}</td><td><span className={`pb-category-badge cat-${player.category.replace('+','plus')}`}>{player.category}</span></td><td>{player.age || '—'}</td><td>{player.experience ? `${player.experience} yrs` : '—'}</td><td>{money(player.basePrice || 1000)}</td><td><span className={`pb-status-badge ${player.status.toLowerCase().replace(' ','-')}`}>{player.status}</span></td><td><select aria-label={`Assign ${player.name} to a team`} value={player.team || 'Unassigned'} onChange={event => setPlayerTeam(player, event.target.value)}><option>Unassigned</option>{teams.map(team => <option key={team.name}>{team.name}</option>)}</select></td></tr>)}</tbody></table>{filteredPlayers.length === 0 && <p className="pb-workspace-empty">No players match those filters.</p>}</div>
  </section>;

  if (section === 'Configuration') return <section className="pb-workspace-page">
    <div className="pb-workspace-heading"><div><span className="pb-workspace-eyebrow">GODREJ NEST CRICKET LEAGUE / SETTINGS</span><h1>Tournament configuration</h1><p>Update the auction rules used by the live auction room.</p></div><span className="pb-workspace-count">SAVED IN THIS BROWSER</span></div>
    <form className="pb-config-grid" onSubmit={event => { event.preventDefault(); notice('Tournament configuration saved.'); }}>
      <article><div className="pb-config-card-title"><Settings size={18}/><div><b>Auction rules</b><small>Budget and squad limits</small></div></div><label>Team purse<input type="number" min="0" step="1000" value={settings.teamPurse} onChange={event => updateSetting('teamPurse', Number(event.target.value))}/></label><label>Bid increment<input type="number" min="100" step="100" value={settings.bidIncrement} onChange={event => updateSetting('bidIncrement', Number(event.target.value))}/></label><label>Maximum players per team<input type="number" min="1" max="30" value={settings.maxPlayers} onChange={event => updateSetting('maxPlayers', Number(event.target.value))}/></label></article>
      <article><div className="pb-config-card-title"><Clock3 size={18}/><div><b>Live bidding</b><small>Timer and auction controls</small></div></div><label>Bid timer (seconds)<input type="number" min="5" max="180" value={settings.timerSeconds} onChange={event => updateSetting('timerSeconds', Number(event.target.value))}/></label>{[['autoSold','Auto sell when timer ends'],['voice','Voice announcements'],['paddle','Paddle mode'],['retentions','Allow player retentions']].map(([key,label])=><label className="pb-config-toggle" key={key}><span>{label}</span><input type="checkbox" checked={settings[key]} onChange={event => updateSetting(key,event.target.checked)}/></label>)}{settings.retentions&&<label>Maximum retentions per team<input type="number" min="0" max="9" value={settings.maxRetentions} onChange={event => updateSetting('maxRetentions',Number(event.target.value))}/></label>}</article>
      <div className="pb-config-actions"><button className="pb-workspace-primary" type="submit">Save configuration</button><button className="pb-workspace-secondary" type="button" onClick={()=>setSettings({bidIncrement:1000,teamPurse:90000,maxPlayers:9,timerSeconds:30,autoSold:false,voice:true,paddle:true,retentions:true,maxRetentions:3})}>Reset defaults</button></div>
    </form>
  </section>;

  if (section === 'Reports') {
    const sold = playerPool.filter(player => player.status === 'Sold').length;
    const unsold = playerPool.filter(player => player.status === 'Unsold').length;
    const completedLots = (sharedState?.bidHistory || []).filter(entry => entry.action === 'Sold' || entry.action === 'Unsold').slice().reverse();
    const teamResults = initialTeams.map(team => {
      const squad = playerPool.filter(player => player.team === team.name && ['Sold', 'Retained'].includes(player.status));
      const spent = squad.reduce((total, player) => total + Number(player.soldPrice || player.basePrice || 0), 0);
      return { ...team, squad, spent, balance: Math.max(0, settings.teamPurse - spent), runs: squad.reduce((total, player) => total + Number(player.runs || 0), 0), wickets: squad.reduce((total, player) => total + Number(player.wickets || 0), 0) };
    });
    return <section className="pb-workspace-page"><div className="pb-workspace-heading"><div><span className="pb-workspace-eyebrow">GODREJ NEST CRICKET LEAGUE / INSIGHTS</span><h1>Auction reports</h1><p>Current player pool and auction progress.</p></div><button className="pb-workspace-secondary" onClick={()=>{const csv=['Lot,Player,Category,Role,Status,Team,Price',...playerPool.map(player=>[player.lot,player.name,player.category,player.role,player.status,player.team,player.soldPrice||player.basePrice].map(value=>`"${String(value??'').replaceAll('"','""')}"`).join(','))].join('\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));link.download='gnpl-auction-report.csv';link.click();URL.revokeObjectURL(link.href);}}>Export CSV <ArrowDownToLine size={15}/></button></div><div className="pb-report-stats"><article><small>TOTAL PLAYERS</small><b>{playerPool.length}</b></article><article><small>AVAILABLE</small><b>{playerPool.filter(player=>player.status==='Available').length}</b></article><article><small>SOLD</small><b>{sold}</b></article><article><small>UNSOLD</small><b>{unsold}</b></article></div><div className="pb-report-panel"><h2>Category breakdown</h2>{['A+','A','B'].map(value=><div key={value}><b>{value}</b><span>{playerPool.filter(player=>player.category===value).length} players</span><i><em style={{width:`${playerPool.length ? (playerPool.filter(player=>player.category===value).length/playerPool.length)*100 : 0}%`}}/></i></div>)}</div><AuctionReportDetails teamResults={teamResults} completedLots={completedLots}/></section>;
  }

  if (section === 'Fixtures') return <section className="pb-workspace-page"><div className="pb-workspace-heading"><div><span className="pb-workspace-eyebrow">GODREJ NEST CRICKET LEAGUE / TOOLS</span><h1>Fixtures &amp; schedule</h1><p>Key GNPL dates and event locations.</p></div></div><div className="pb-schedule-list"><article><span>21 NOV</span><div><b>Player auction</b><p>Saturday · 7:00 PM · 7th Floor Podium</p></div><strong>SCHEDULED</strong></article><article><span>13 DEC</span><div><b>GNPL match day</b><p>Kandivali Turf Zone · Mumbai</p></div><strong>UPCOMING</strong></article></div><div className="pb-workspace-note">Match fixtures will appear here after the match schedule is published.</div></section>;

  if (section === 'Banner Creator') return <section className="pb-workspace-page"><div className="pb-workspace-heading"><div><span className="pb-workspace-eyebrow">GODREJ NEST CRICKET LEAGUE / TOOLS</span><h1>Stream banner creator</h1><p>Choose a broadcast overlay style for the live auction.</p></div></div><div className="pb-banner-template-grid">{[['Classic','#f13258'],['Aerodynamic','#31b9a0'],['Gold Royale','#e6a52e']].map(([name,color])=><article key={name} style={{'--template':color}}><div className="pb-banner-preview"><span>GNPL 2026</span><b>LIVE AUCTION</b><small>PLAYER NAME · CURRENT BID</small></div><h2>{name}</h2><p>Live player, bid and team graphics for your stream.</p><button className="pb-workspace-secondary" onClick={()=>notice(`${name} overlay selected.`)}>Select overlay</button></article>)}</div></section>;

  if (section === 'User & Roles') return <section className="pb-workspace-page"><div className="pb-workspace-heading"><div><span className="pb-workspace-eyebrow">ADMINISTRATION / ACCESS</span><h1>Users &amp; roles</h1><p>Organizer access for this tournament workspace.</p></div><span className="pb-workspace-count">ADMIN ONLY</span></div><div className="pb-users-table"><div><span className="pb-user-initials">AS</span><div><b>Abhishek</b><small>Primary tournament administrator</small></div><strong>ADMIN</strong></div><p>Only administrators authenticated with the configured admin password can open the Auction Portal.</p></div></section>;

  if (section === 'Billing & Plan') return <section className="pb-workspace-page"><div className="pb-workspace-heading"><div><span className="pb-workspace-eyebrow">ADMINISTRATION / PLAN</span><h1>Billing &amp; plan</h1><p>Current tournament workspace allowance.</p></div></div><article className="pb-plan-card"><span>GNPL WORKSPACE</span><h2>Organizer plan</h2><p>1 tournament workspace · 4 registered teams · {playerPool.length} imported players</p><div><b>ACTIVE</b><small>Plan billing is managed by the PlayBid account owner.</small></div></article></section>;

  return <section className="pb-workspace-page"><div className="pb-workspace-heading"><div><span className="pb-workspace-eyebrow">SUPPORT / GNPL AUCTION</span><h1>Help &amp; guide</h1><p>Quick instructions for running the auction.</p></div></div><div className="pb-help-list"><details open><summary>How do I start a player lot?</summary><p>Open Auction, select a player from Upcoming Lots, then Start Bidding.</p></details><details><summary>How do teams place bids?</summary><p>Choose a team in Quick Bidder to record the next bid. Use Undo Last Bid if a click needs to be reversed.</p></details><details><summary>How do I assign players to squads?</summary><p>Open Teams, expand a team, then choose an available player from its squad controls.</p></details><details><summary>Where are tournament rules?</summary><p>Open Configuration in the Tournament section to edit purse, bid increment, timer and retention settings.</p></details></div></section>;
}

function AuctionLobby({ onEnter, notice, onLogout, playerPool, setPlayerPool, sharedAuction, setSharedAuction, realtimeAvailable }) {
  const [section, setSection] = useState('Auction');
  const [profileOpen, setProfileOpen] = useState(false);
  const navGroups = [
    ['MAIN', [['Home', LayoutDashboard], ['Tournaments', Trophy]]],
    ['TOURNAMENT', [['Teams', Wallet], ['Players', Users], ['Auction', Hammer], ['Configuration', Settings], ['Reports', Image]]],
    ['TOOLS', [['Fixtures', Clock3], ['Banner Creator', Image]]],
    ['ADMINISTRATION', [['User & Roles', Users], ['Billing & Plan', Wallet]]],
    ['SUPPORT', [['Help & Guide', CircleHelp]]],
  ];
  const tournamentView = section === 'Tournaments';
  const arenaHomeView = section === 'Auction';
  return <div className="pb-lobby">
    <aside className="pb-lobby-side"><div className="pb-brand"><span><Hammer size={20}/></span><b>PlayBid<small>AUCTION PLATFORM</small></b></div><nav>{navGroups.map(([group,items])=><section key={group}><small>{group}</small>{items.map(([name,Icon])=><button key={name} className={section===name?'selected':''} onClick={()=>setSection(name)}><Icon size={17}/>{name}</button>)}</section>)}</nav></aside>
    <main className="pb-lobby-main"><header className="pb-lobby-top"><button className="pb-tournament-chip" onClick={()=>notice('Godrej Nest Cricket League is the selected tournament.')}><span>G</span><b>Godrej Nest Cricket League<small>Selected Tournament</small></b><ChevronDown size={13}/></button><div className="pb-lobby-tools"><button onClick={()=>document.body.classList.toggle('pb-dark-preview')} aria-label="Toggle appearance">◐</button><button onClick={()=>notice('You’re all caught up.')} aria-label="Notifications"><Bell size={17}/></button><button className="pb-user-chip" onClick={()=>setProfileOpen(!profileOpen)}><i>AS</i><b>Abhishek<small>⌄</small></b></button>{profileOpen&&<div className="pb-profile-menu"><b>Abhishek</b><small>Administrator</small><button onClick={()=>notice('Admin access is controlled by the configured admin password.')}>Account access</button><button onClick={onLogout}>Sign out</button></div>}</div></header>
      {tournamentView ? <TournamentManagement onGoAuction={()=>setSection('Auction')} onOpenTeams={()=>setSection('Teams')} onOpenPlayers={()=>setSection('Players')} onOpenConfiguration={()=>setSection('Configuration')} notice={notice} playerCount={playerPool.length}/> : arenaHomeView ? <div className="pb-arena-lobby"><div className="pb-hammer-orb"><Hammer size={24}/></div><h1>Live Auction Arena</h1><div className="pb-arena-summary"><div><small>TOURNAMENT</small><b>Godrej Nest Cricket League</b><i>TennisBall</i></div><div><small>REGISTERED TEAMS</small><b>4 / 6</b><span>Franchises configured</span></div><div><small>REGISTERED PLAYERS</small><b>{playerPool.length}</b><span>Ready in player pool</span></div><div><small>STATUS</small><b className="pb-arena-status">{realtimeAvailable?'REAL-TIME SYNC ON':'SYNC NEEDS SETUP'}</b><span>Sat, 21 Nov · 7:00 PM · 7th Floor Podium</span></div></div>
        <div className="pb-arena-links"><div><span className="pb-link-icon pink"><Image size={17}/></span><div><b>Projector Screen ↗</b><small>Showcase live bids on a large display</small></div><button onClick={()=>notice('Projector screen link copied.')}><Share2 size={16}/></button></div><div><span className="pb-link-icon green"><Globe size={17}/></span><div><b>Public Live Auction ↗</b><small>Public arena link for audience</small></div><button onClick={()=>notice('Public auction link copied.')}><Share2 size={16}/></button></div><div className="pb-overlays"><span className="pb-link-icon blue"><Tv size={17}/></span><div><b>Stream Overlays ↗</b><small>OBS / vMix graphics for live streams</small></div><div className="pb-overlay-tags"><button onClick={()=>notice('Classic overlay selected.')}>Classic ↗</button><button onClick={()=>notice('Aerodynamic overlay selected.')}>Aerodynamic ↗</button><button onClick={()=>notice('Gold Royale overlay selected.')}>Gold Royale ↗</button></div></div></div>
        <button className="pb-enter-arena" onClick={onEnter}>ENTER LIVE AUCTION <Hammer size={16}/></button>
      </div> : <AuctionWorkspacePage section={section} playerPool={playerPool} setPlayerPool={setPlayerPool} notice={notice} onNavigate={setSection} sharedState={sharedAuction} setSharedAuction={setSharedAuction}/>}
    </main>{notice&&<div className="pb-toast">{notice}</div>}
  </div>;
}

function AuctionInitialization({ onCancel, onContinue, playerPool, settings }) {
  const rows=[['TOURNAMENT NAME','Godrej Nest Cricket League'],['PRIZE POOL (PURSE)',money(settings.teamPurse)],['TOTAL REGISTERED TEAMS','4 / 6'],['BID INCREMENT',money(settings.bidIncrement)],['MAX PLAYERS PER TEAM',`${settings.maxPlayers} Players`],['TIMER SECONDS',`${settings.timerSeconds}s`],['AUTO SOLD ENABLED',settings.autoSold?'Yes':'No'],['VOICE ANNOUNCEMENTS',settings.voice?'Enabled':'Disabled'],['PADDLE MODE',settings.paddle?'Enabled':'Disabled'],['ALLOW RETENTIONS',settings.retentions?`Yes (Max: ${settings.maxRetentions})`:'No']];
  return <div className="pb-init-back"><section className="pb-init-dialog" role="dialog" aria-modal="true" aria-labelledby="pb-init-title"><header><h2 id="pb-init-title"><span>⚠</span> Auction Initialization Overview</h2><button aria-label="Close" onClick={onCancel}><X size={17}/></button></header><div className="pb-init-scroll"><div className="pb-init-settings">{rows.map(([label,value])=><div key={label}><small>{label}</small><b>{value}</b></div>)}</div><div className="pb-retain-tip"><span>💡</span><p><b>How to retain players:</b> Go to the <button onClick={onCancel}>Teams</button> page, click <strong>View Squad</strong> for the target team, then assign a player from the team squad controls.</p></div><h3 className="pb-squad-title">Team Squad Registries</h3><div className="pb-squad-grid">{initialTeams.map(team=>{const squad=playerPool.filter(player=>player.team===team.name&&player.status!=='Unsold');return <article key={team.name}><header><b>{team.name}</b><span>Squad: {squad.length} / {settings.maxPlayers}</span></header><div><span>Purse Balance:</span><strong>{money(Math.max(0,settings.teamPurse-squad.filter(player=>['Sold','Retained'].includes(player.status)).reduce((total,player)=>total+Number(player.soldPrice||player.basePrice||0),0)))}</strong></div><small>Retained Players:</small><i>{squad.filter(player=>player.status==='Retained').length?squad.filter(player=>player.status==='Retained').map(player=>player.name).join(', '):'No players retained'}</i></article>})}</div></div><footer><button onClick={onCancel}>Cancel</button><button className="pb-init-continue" onClick={onContinue}>Continue</button></footer></section></div>;
}

function AuctionRoom({ onExit, notice, playerPool, setPlayerPool, auctionState, setAuctionState }) {
  const [initOpen,setInitOpen]=useState(true);
  const settings=auctionState.settings||readAuctionSettings();
  const [fast,setFast]=useState(false); const [filter,setFilter]=useState('All'); const [dialog,setDialog]=useState('');
  const started=Boolean(auctionState.started), currentPlayer=auctionState.currentPlayer||'', selectedPlayer=auctionState.selectedPlayer||null, activeTeam=auctionState.activeTeam||'', bid=Number(auctionState.bid)||1000, bidHistory=auctionState.bidHistory||[];
  const setStarted=value=>setAuctionState(previous=>({...previous,started:typeof value==='function'?value(Boolean(previous.started)):value}));
  const setCurrentPlayer=value=>setAuctionState(previous=>({...previous,currentPlayer:typeof value==='function'?value(previous.currentPlayer||''):value}));
  const setSelectedPlayer=value=>setAuctionState(previous=>({...previous,selectedPlayer:typeof value==='function'?value(previous.selectedPlayer||null):value}));
  const setActiveTeam=value=>setAuctionState(previous=>({...previous,activeTeam:typeof value==='function'?value(previous.activeTeam||''):value}));
  const setBid=value=>setAuctionState(previous=>({...previous,bid:typeof value==='function'?value(Number(previous.bid)||1000):value}));
  const setBidHistory=value=>setAuctionState(previous=>({...previous,bidHistory:typeof value==='function'?value(previous.bidHistory||[]):value}));
  const teams=initialTeams.map(team=>[team.short,team.name,team.color]);
  const teamSquad=name=>playerPool.filter(player=>player.team===name&&player.status!=='Unsold');
  const teamSpent=name=>playerPool.filter(player=>player.team===name&&['Sold','Retained'].includes(player.status)).reduce((total,player)=>total+Number(player.soldPrice||player.basePrice||0),0);
  const teamPurse=name=>Math.max(0,settings.teamPurse-teamSpent(name));
  const availablePlayers=playerPool.filter(player=>player.status==='Available');
  const visibleLots=availablePlayers.filter(player=>filter==='All'||player.category===filter);
  const categoryCount=category=>playerPool.filter(player=>player.category===category).length;
  const availableCount=availablePlayers.length;
  const playerInitials=selectedPlayer?.name.split(' ').map(part=>part[0]).slice(0,2).join('')||'GN';
  const soldCount=playerPool.filter(player=>player.status==='Sold').length;
  const unsoldCount=playerPool.filter(player=>player.status==='Unsold').length;
  const pickPlayer=player=>{setSelectedPlayer(player);setCurrentPlayer(player.name);setPlayerPool(pool=>pool.map(item=>item.lot===player.lot?{...item,status:'In Auction'}:item));setStarted(false);setActiveTeam('');setBid(player.basePrice||1000);};
  const drawPlayer=()=>{const candidate=visibleLots[Math.floor(Math.random()*visibleLots.length)];if(candidate)pickPlayer(candidate);};
  const currentBidHistory=bidHistory.filter(entry=>entry.lot===selectedPlayer?.lot);
  const recordTeamBid=team=>{if(!selectedPlayer)return;const squadCount=teamSquad(team).length;if(squadCount>=settings.maxPlayers){notice(`${team} has reached its ${settings.maxPlayers}-player squad limit.`);return;}const amount=activeTeam?bid+settings.bidIncrement:(selectedPlayer.basePrice||1000);if(amount>teamPurse(team)){notice(`${team} does not have enough purse for this bid.`);return;}setActiveTeam(team);setBid(amount);const entry={id:`${Date.now()}-${Math.random().toString(36).slice(2,7)}`,lot:selectedPlayer.lot,player:selectedPlayer.name,team,amount,action:'Bid',createdAt:new Date().toISOString()};setBidHistory(previous=>{const next=[...previous,entry];try{localStorage.setItem('playbid_bid_history',JSON.stringify(next));}catch{}return next;});};
  const undoBid=()=>{const effectiveBids=currentBidHistory.filter(entry=>entry.action==='Bid'&&!currentBidHistory.some(event=>event.action==='Undo'&&event.undoneId===entry.id));const latest=effectiveBids.at(-1);if(!latest)return;const event={id:`${Date.now()}-${Math.random().toString(36).slice(2,7)}`,lot:selectedPlayer.lot,player:selectedPlayer.name,team:latest.team,amount:latest.amount,action:'Undo',undoneId:latest.id,createdAt:new Date().toISOString()};const next=[...bidHistory,event];setBidHistory(next);try{localStorage.setItem('playbid_bid_history',JSON.stringify(next));}catch{}const previous=effectiveBids.at(-2);setActiveTeam(previous?.team||'');setBid(previous?.amount||selectedPlayer?.basePrice||1000);};
  const returnPlayerToPool=()=>{if(!selectedPlayer)return;setPlayerPool(pool=>pool.map(item=>item.lot===selectedPlayer.lot?{...item,status:'Available'}:item));setCurrentPlayer('');setSelectedPlayer(null);};
  const closePlayer=status=>{if(!selectedPlayer)return;const winningTeam=status==='Sold'?(activeTeam||'Team 1'):'';const outcome={id:`${Date.now()}-${Math.random().toString(36).slice(2,7)}`,lot:selectedPlayer.lot,player:selectedPlayer.name,team:winningTeam,amount:status==='Sold'?bid:0,action:status,createdAt:new Date().toISOString()};setBidHistory(previous=>[...previous,outcome]);setPlayerPool(pool=>pool.map(item=>item.lot===selectedPlayer.lot?{...item,status,soldPrice:status==='Sold'?bid:null,team:status==='Sold'?winningTeam:'Unassigned'}:item));setStarted(false);setCurrentPlayer('');setSelectedPlayer(null);setActiveTeam('');};
  const openDialog=name=>setDialog(name);
  return <div className="pb-room"><aside className="pb-room-rail"><button className="pb-rail-trophy" onClick={()=>openDialog('Full standings')}><Trophy/></button><button className="pb-rail-auction active" onClick={()=>setStarted(!started)}><Hammer/></button><button className="pb-rail-info" onClick={()=>openDialog('Auction information')}>i</button><div className="pb-rail-teams">{teams.map(([id,name,color])=><button key={id} style={{'--team':color}} onClick={()=>started?recordTeamBid(name):openDialog(`${name} standings`)}>{id}</button>)}</div></aside>
    <main className="pb-room-main"><header className="pb-room-header"><div className="pb-room-headleft"><button className="pb-room-menu" onClick={()=>openDialog('Auction menu')}><Menu size={18}/></button><button className="pb-exit" onClick={onExit}><ArrowLeft size={15}/> Exit</button><span className="pb-room-trophy"><Trophy size={17}/></span><b>Godrej Nest Cricket League</b><i className="pb-live-pill">● LIVE</i></div><div className="pb-lot-count"><b>AVAILABLE <strong>{availableCount}</strong></b><span/> <b>SOLD <strong>{soldCount}</strong></b><span/> <b>UNSOLD <strong>{unsoldCount}</strong></b></div><div className="pb-room-tools"><button onClick={()=>openDialog('Keyboard shortcuts')} title="Shortcuts">▦</button><button onClick={()=>notice('Auction room link copied.')} title="Copy link"><Link size={16}/></button><button onClick={()=>openDialog('Public auction')} title="Public view"><Globe size={16}/></button><button onClick={()=>notice('Sound settings')} title="Sound"><Volume2 size={16}/></button><button className="pb-room-settings" onClick={()=>openDialog('Auction settings')} title="Settings"><Settings size={17}/></button></div></header>
      <div className="pb-room-body"><section className={`pb-current-lot${started?' bidding':''}`}>{currentPlayer&&!started&&<button className="pb-lot-close" onClick={returnPlayerToPool}><X size={17}/></button>}{!currentPlayer?<div className="pb-no-active"><span className="pb-no-active-hammer"><Hammer size={53}/></span><h2>No Active Player Under the Hammer</h2><label>⚲ CATEGORY : <select value={filter} onChange={e=>setFilter(e.target.value)}><option value="All">All Categories ({availableCount} Players)</option><option value="A">A ({categoryCount('A')} Players)</option><option value="A+">A+ ({categoryCount('A+')} Players)</option><option value="B">B ({categoryCount('B')} Players)</option></select></label><div><button onClick={()=>notice('There is no recently closed lot to undo.')}>↶ Undo Last Closed Lot</button><button onClick={drawPlayer}>🎲 Draw Random Player ({visibleLots.length})</button></div></div>:!started?<div className="pb-prestart-player"><span className="pb-lot-label">LOT #{selectedPlayer?.lot || 39}</span><div className="pb-murari-photo">{selectedPlayer?.photo&&<img src={selectedPlayer.photo} alt={selectedPlayer.name}/>}<span>{!selectedPlayer?.photo&&playerInitials}</span><i><Hammer size={15}/></i></div><h2>{currentPlayer.toUpperCase()} <span className="pb-role-blue">{(selectedPlayer?.role || 'Batter').toUpperCase()}</span></h2><p>Age: <b>{selectedPlayer?.age || '—'} {selectedPlayer?.age?'Yrs':''}</b><i/> Base Price: <strong>P {Number(selectedPlayer?.basePrice || 1000).toLocaleString('en-IN')}</strong></p><div className="pb-stats-row">{[['MATCHES',selectedPlayer?.matches||0],['RUNS',selectedPlayer?.runs||0],['WICKETS',selectedPlayer?.wickets||0],['BAT',selectedPlayer?.batting||'—'],['BOWL',selectedPlayer?.bowling||'—'],['EXP',selectedPlayer?.experience?`${selectedPlayer.experience}y`:'—']].map(([a,b])=><div key={a}><small>{a}</small><b>{b}</b></div>)}</div><div className="pb-prestart-actions"><button onClick={()=>notice('There is no recently closed lot to undo.')}>↶ Undo Last Closed Lot</button><button onClick={()=>setStarted(true)}>Start Bidding</button></div></div>:<div className="pb-live-player-card"><div className="pb-live-accent"/><div className="pb-player-photo-large">{selectedPlayer?.photo&&<img src={selectedPlayer.photo} alt={selectedPlayer.name}/>}<span>{!selectedPlayer?.photo&&playerInitials}</span></div><div className="pb-player-card-main"><small className="pb-category-letter">{selectedPlayer?.category || 'B'}</small><h2>{currentPlayer.toUpperCase()}</h2><div className="pb-live-role"><span>Age {selectedPlayer?.age || '—'}</span><b>{(selectedPlayer?.role || 'Batter').toUpperCase()}</b></div><div className="pb-live-base">Base Price: <strong>P {(selectedPlayer?.basePrice || 1000).toLocaleString('en-IN')}</strong></div><div className="pb-stats-row">{[['MATCHES',selectedPlayer?.matches||0],['RUNS',selectedPlayer?.runs||0],['WICKETS',selectedPlayer?.wickets||0],['BAT',selectedPlayer?.batting||'—'],['BOWL',selectedPlayer?.bowling||'—'],['EXP',selectedPlayer?.experience?`${selectedPlayer.experience}y`:'—']].map(([a,b])=><div key={a}><small>{a}</small><b>{b}</b></div>)}</div></div><div className="pb-current-price"><small>{activeTeam?'CURRENT HIGHEST BID':'BASE PRICE'}</small><strong key={bid} className={activeTeam?'pb-bid-amount':''}>{activeTeam?`P ${bid.toLocaleString('en-IN')}`:`P ${(selectedPlayer?.basePrice || 1000).toLocaleString('en-IN')}`}</strong><span>{activeTeam?activeTeam.toUpperCase():'No Bids Placed'}</span><span>Next Bid: <b>P {activeTeam?(bid+settings.bidIncrement).toLocaleString('en-IN'):(selectedPlayer?.basePrice || 1000).toLocaleString('en-IN')}</b></span></div></div>}</section>
        {started?<section className="pb-live-controls"><div className="pb-lot-action-row"><button className="pb-undo-bid" onClick={undoBid}>↶ UNDO LAST BID</button><button className="pb-mark-unsold" onClick={()=>{closePlayer('Unsold');notice('Player marked unsold.');}}>× MARK UNSOLD</button><button className="pb-sell-player" disabled={!activeTeam} onClick={()=>{closePlayer('Sold');notice('Player sold to selected team.');}}>✓ SELL</button></div><div className="pb-quick-bidder"><div className="pb-quick-top"><b><Zap size={16}/> QUICK BIDDER</b><div><button className={fast?'fast-on':''} onClick={()=>setFast(!fast)}><Zap size={13}/> Fast Mode: {fast?'ON':'OFF'}</button><button onClick={()=>openDialog('Arrange teams')}>↕ Arrange</button><button onClick={()=>openDialog('Keyboard shortcuts')}>▦ Shortcuts</button><button onClick={()=>openDialog('Bid History')}>Bid History ({currentBidHistory.length})</button><button onClick={()=>openDialog('Custom Bid')}>Custom Bid</button></div></div><div className="pb-quick-teams">{teams.map(([id,name,color])=><button key={id} className={activeTeam===name?'is-leading':''} style={{'--team':color}} onClick={()=>recordTeamBid(name)}><span><i>{id}</i>{name}</span><b>P {activeTeam===name?bid.toLocaleString('en-IN'):teamPurse(name).toLocaleString('en-IN')}</b><small>{activeTeam===name?'LEADING BID':'⊖ Not Active'}</small></button>)}</div></div></section>:<section className="pb-upcoming"><div className="pb-upcoming-head"><h3>Upcoming Lots <span>{availableCount} REMAINING</span></h3><label>⚲ Category: <select value={filter} onChange={e=>setFilter(e.target.value)}><option value="All">All Categories ({availableCount} Players)</option><option value="A">A ({categoryCount('A')} Players)</option><option value="A+">A+ ({categoryCount('A+')} Players)</option><option value="B">B ({categoryCount('B')} Players)</option></select></label></div><div className="pb-upcoming-scroll"><table><thead><tr><th>LOT #</th><th>PLAYER</th><th>CATEGORY</th><th>BASE</th><th>ACTION</th></tr></thead><tbody>{visibleLots.map(player=><tr key={player.sourceId||player.lot}><td>#{player.lot}</td><td><span className="pb-upcoming-player"><i>{player.photo&&<img src={player.photo} alt=""/>}{!player.photo&&player.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</i><b>{player.name}</b><em>{(player.role || 'Player').toUpperCase()}</em></span></td><td>{player.category}</td><td>P {Number(player.basePrice || 1000).toLocaleString('en-IN')}</td><td><button onClick={()=>{pickPlayer(player);setStarted(true);}}>Start</button></td></tr>)}</tbody></table></div></section>}
        <aside className="pb-room-standings"><div className="pb-standings-head"><b>TEAMS (4)</b><button onClick={()=>openDialog('Full standings')}>View Full Standings</button></div>{teams.map(([id,name,color])=><button className={`pb-standings-team${activeTeam===name?' pb-team-current-bidder':''}`} key={id} onClick={()=>openDialog(`${name} standings`)}><i style={{'--team':color}}>{id}</i><b>{name}</b><span className="pb-standings-squad">{teamSquad(name).length}/{settings.maxPlayers} · {teamSquad(name).reduce((sum,p)=>sum+Number(p.runs||0),0)} R · {teamSquad(name).reduce((sum,p)=>sum+Number(p.wickets||0),0)} W</span><strong>{money(teamPurse(name))}⌄</strong></button>)}</aside>
      </div>{started&&<section className="pb-live-bid-feed"><header><div><span className="pb-feed-live-dot"/><b>Live bid activity</b></div><small>{currentBidHistory.length} events · synced between admin sessions</small></header>{currentBidHistory.length?currentBidHistory.slice().reverse().slice(0,5).map(event=><article key={event.id} className={`feed-${event.action.toLowerCase()}`}><span>{event.action==="Bid"?"BID":event.action==="Undo"?"UNDO":event.action==="Sold"?"SOLD":"UNSOLD"}</span><b>{event.team||"Auction desk"}</b><small>{event.action==="Bid"||event.action==="Sold"?`P ${Number(event.amount).toLocaleString("en-IN")}`:event.player}</small><time>{new Date(event.createdAt).toLocaleTimeString("en-IN",{hour:"2-digit",minute:"2-digit",second:"2-digit"})}</time></article>):<p>Team bids and completed player lots will appear here.</p>}</section>}<footer className="pb-room-footer">Powered by <b>PlayBid</b> — Host your Cricket Auction</footer></main>
      {dialog&&<div className="pb-dialog-back" onMouseDown={e=>e.target===e.currentTarget&&setDialog('')}><section><button className="pb-dialog-close" onClick={()=>setDialog('')}><X size={17}/></button><small>GODREJ NEST CRICKET LEAGUE</small><h3>{dialog}</h3>{dialog==='Bid History'?<div className="pb-bid-history-list">{currentBidHistory.length?currentBidHistory.slice().reverse().map(entry=><div key={entry.id}><span><b>{entry.action==='Undo'?`Undo · ${entry.team}`:entry.team}</b><small>{entry.action==='Undo'?'Bid reversed · ':''}{entry.player} · {new Date(entry.createdAt).toLocaleString()}</small></span><strong>P {Number(entry.amount).toLocaleString('en-IN')}</strong></div>):<p>No bids recorded for this player yet.</p>}</div>:<p>{dialog==='Custom Bid'?'Enter a custom bid amount for this player.':dialog==='Auction settings'?'Manage bidding increments, timer, sound, and auction rules.':'Auction control tools for the selected tournament.'}</p>}{dialog==='Custom Bid'&&<input type="number" min="1000" step="1000" placeholder="Enter bid amount"/>}<button className="pb-dialog-action" onClick={()=>{setDialog('');if(dialog==='Custom Bid'){setActiveTeam('Team 1');setBid(v=>v+5000);}}}>{dialog==='Full standings'||dialog==='Bid History'?'Close':'Continue'}</button></section></div>}
    {initOpen&&<AuctionInitialization onCancel={onExit} onContinue={()=>setInitOpen(false)} playerPool={playerPool} settings={settings}/>}
  </div>;
}

export default function PlayBid({ onLogout }) {
  const [signedIn, setSignedIn] = useState(!window.location.pathname.startsWith('/login'));
  const [tab, setTab] = useState('Auction');
  const [arenaEntered, setArenaEntered] = useState(false);
  const [auctionPlayerPool, setAuctionPlayerPool] = useState(() => {
    try { const saved = JSON.parse(localStorage.getItem(PLAYER_POOL_KEY) || 'null'); return Array.isArray(saved) && saved.length ? saved : playerData; }
    catch { return playerData; }
  });
  const [syncReady, setSyncReady] = useState(false);
  const [realtimeAvailable, setRealtimeAvailable] = useState(true);
  const [sharedAuction, setSharedAuction] = useState({});
  const [players, setPlayers] = useState(initialPlayers);
  const [teams] = useState(initialTeams);
  const [query, setQuery] = useState('');
  const [auctionLive, setAuctionLive] = useState(true);
  const [notice, setNotice] = useState('');
  const [mobileNav, setMobileNav] = useState(false);
  const [showNewTournament, setShowNewTournament] = useState(false);
  const sold = players.filter(p => p.status === 'Sold').length;
  const filteredPlayers = useMemo(() => players.filter(p => `${p.name} ${p.role} ${p.team} ${p.status}`.toLowerCase().includes(query.toLowerCase())), [players, query]);
  const announce = msg => { setNotice(msg); window.setTimeout(() => setNotice(''), 2600); };
  const navItems = [
    { title: 'WORKSPACE', items: [['Overview', LayoutDashboard], ['Live auction', Zap], ['Players', UserRound], ['Teams', Users]] },
    { title: 'TOURNAMENT', items: [['Registration', ShieldCheck], ['Reports', Activity], ['Settings', Settings]] },
  ];
  const bid = () => setPlayers(ps => ps.map((p, i) => i === 0 ? { ...p, bid: p.bid + 5000 } : p));
  const decideLot = status => setPlayers(ps => ps.map((p, i) => i === 0 ? { ...p, status, team: status === 'Sold' ? 'Mumbai Strikers' : '' } : p));

  useEffect(() => {
    let alive = true;
    const load = async () => {
      try {
        const [rosterResponse, stateResponse] = await Promise.all([
          fetch('/api/players', { cache: 'no-store' }),
          fetch('/api/auction-state', { credentials: 'same-origin', cache: 'no-store' }),
        ]);
        if (!alive) return;
        const saved = JSON.parse(localStorage.getItem(PLAYER_POOL_KEY) || '[]');
        let roster = playerData;
        if (rosterResponse.ok) {
          const result = await rosterResponse.json();
          if (Array.isArray(result.players) && result.players.length) roster = mapGnplRoster(result.players);
        }
        const shared = stateResponse.ok ? (await stateResponse.json()).state : null;
        if (stateResponse.ok) setRealtimeAvailable(true); else setRealtimeAvailable(false);
        setAuctionPlayerPool(mergePlayerStates(roster, shared?.playerPool?.length ? shared.playerPool : saved));
        setSharedAuction(shared?.auction || {});
        setSyncReady(true);
      } catch {
        if (alive) { setRealtimeAvailable(false); setSyncReady(true); }
      }
    };
    void load();
    return () => { alive = false; };
  }, []);
  useEffect(() => {
    if (!syncReady) return;
    const timer = window.setTimeout(() => {
      try { localStorage.setItem(PLAYER_POOL_KEY, JSON.stringify(auctionPlayerPool)); } catch {}
      fetch('/api/auction-state', { method: 'PUT', credentials: 'same-origin', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ state: { playerPool: auctionPlayerPool, auction: sharedAuction } }) })
        .then(response => setRealtimeAvailable(response.ok)).catch(() => setRealtimeAvailable(false));
    }, 700);
    return () => window.clearTimeout(timer);
  }, [auctionPlayerPool, sharedAuction, syncReady]);
  useEffect(() => {
    if (!syncReady) return;
    let active = true;
    const timer = window.setInterval(async () => {
      try {
        const response = await fetch('/api/auction-state', { credentials: 'same-origin', cache: 'no-store' });
        if (!active) return;
        if (!response.ok) { setRealtimeAvailable(false); return; }
        const { state } = await response.json();
        setRealtimeAvailable(true);
        if (Array.isArray(state?.playerPool)) setAuctionPlayerPool(current => JSON.stringify(current) === JSON.stringify(state.playerPool) ? current : mergePlayerStates(state.playerPool, current));
        if (state?.auction && JSON.stringify(state.auction) !== JSON.stringify(sharedAuction)) setSharedAuction(state.auction);
      } catch { if (active) setRealtimeAvailable(false); }
    }, 2500);
    return () => { active = false; window.clearInterval(timer); };
  }, [syncReady, sharedAuction]);
  useEffect(() => {
    if (!syncReady) return;
    let active = true;
    const timer = window.setInterval(async () => {
      try {
        const response = await fetch('/api/players', { cache: 'no-store' });
        if (!response.ok || !active) return;
        const result = await response.json();
        if (Array.isArray(result.players) && result.players.length) {
          const roster = mapGnplRoster(result.players);
          setAuctionPlayerPool(current => {
            const merged = mergePlayerStates(roster, current);
            return JSON.stringify(current) === JSON.stringify(merged) ? current : merged;
          });
        }
      } catch { /* Keep the last loaded roster available during brief network interruptions. */ }
    }, 30000);
    return () => { active = false; window.clearInterval(timer); };
  }, [syncReady]);

  if (!signedIn) return <main className="pb-login">
    <div className="pb-login-left"><a className="pb-logo" href="/"><span className="pb-logo-mark"><Command size={22} /></span><span>playbid<small>CRICKET AUCTION PLATFORM</small></span></a><div className="pb-login-promo"><div className="pb-live-label"><i /> LIVE AUCTION CONTROL ROOM</div><h1>Every bid.<br /><em>One big moment.</em></h1><p>Run your tournament from the first player registration to the final team sheet.</p><div className="pb-login-score"><span><b>₹78,000</b><small>LEADING BID</small></span><span className="pb-score-sep" /><span><b>22 sec</b><small>TIME LEFT</small></span><span className="pb-login-ball">🏏</span></div></div><div className="pb-login-foot">BUILT FOR THE LOVE OF THE GAME <span>© 2026 PlayBid</span></div></div>
    <div className="pb-login-right"><form className="pb-login-form" onSubmit={e => { e.preventDefault(); setSignedIn(true); window.history.replaceState({}, '', '/dashboard'); }}><div className="pb-mobile-logo"><span className="pb-logo-mark"><Command size={20} /></span><b>playbid</b></div><div className="pb-kicker">WELCOME BACK</div><h2>Sign in to your<br /><em>workspace.</em></h2><p className="pb-login-hint">Enter your account details to continue to your tournaments.</p><label>Email address<input type="email" autoComplete="username" required placeholder="you@example.com" /></label><label>Password<div className="pb-password"><input type="password" autoComplete="current-password" required placeholder="Enter your password" /><button type="button" onClick={e => { const input=e.currentTarget.previousSibling; input.type=input.type==='password'?'text':'password'; }}>{'Show'}</button></div></label><div className="pb-login-options"><label className="pb-check"><input type="checkbox" defaultChecked /> Remember me</label><button type="button" onClick={() => announce('Password reset is not connected in this local preview.')}>Forgot password?</button></div><button className="pb-primary pb-signin">Sign in <ArrowRight size={17} /></button><div className="pb-divider"><span /> SECURE ORGANIZER ACCESS <span /></div><div className="pb-signup">New to PlayBid? <button type="button" onClick={() => announce('Account creation is not connected in this local preview.')}>Create an account</button></div><div className="pb-demo-note"><ShieldCheck size={16} /> Local interface preview · credentials are not sent anywhere</div></form><div className="pb-login-copyright">Privacy <span>·</span> Terms <span>·</span> Help centre</div></div>{notice && <div className="pb-toast">{notice}</div>}
  </main>;

  if (!signedIn) return null;
  return arenaEntered
    ? <AuctionRoom onExit={() => setArenaEntered(false)} notice={announce} playerPool={auctionPlayerPool} setPlayerPool={setAuctionPlayerPool} auctionState={sharedAuction} setAuctionState={setSharedAuction} />
    : <AuctionLobby onEnter={() => setArenaEntered(true)} notice={announce} onLogout={onLogout} playerPool={auctionPlayerPool} setPlayerPool={setAuctionPlayerPool} sharedAuction={sharedAuction} setSharedAuction={setSharedAuction} realtimeAvailable={realtimeAvailable} />;

  return <div className="pb-app">
    <aside className={`pb-sidebar${mobileNav ? ' pb-sidebar-open' : ''}`}><a className="pb-logo" href="/dashboard"><span className="pb-logo-mark"><Command size={21} /></span><span>playbid<small>CRICKET AUCTION PLATFORM</small></span></a><div className="pb-workspace-select"><span className="pb-ws-icon">GN</span><span><b>Godrej Nest Premier League</b><small>Organizer workspace</small></span><ChevronDown size={15} /></div><div className="pb-nav-scroll">{navItems.map(group => <div className="pb-nav-group" key={group.title}><div className="pb-nav-title">{group.title}</div>{group.items.map(([name, Icon]) => <button key={name} className={`pb-nav-item${tab === name ? ' active' : ''}`} onClick={() => { setTab(name); setMobileNav(false); }}><Icon size={17} strokeWidth={1.8} />{name}{name === 'Live auction' && <i className="pb-nav-live" />}</button>)}</div>)}<div className="pb-side-plan"><div><Zap size={16} /> DEMO PLAN</div><p>You're all set to explore the auction room.</p><span className="pb-plan-bar"><i /></span><small>1 of 1 demo tournament</small><button onClick={() => announce('Plan options are available on playbid.in.')}>View plans <ArrowRight size={13} /></button></div></div><div className="pb-sidebar-bottom"><button className="pb-help" onClick={() => announce('Help centre is not connected in this local preview.')}><CircleHelp size={17} /> Help centre <ArrowRight size={14} /></button><button className="pb-profile" onClick={() => setTab('Settings')}><span className="pb-avatar">TS</span><span><b>The Still Story</b><small>Organizer</small></span><MoreHorizontal size={17} /></button></div></aside>
    <main className="pb-main"><header className="pb-topbar"><button className="pb-mobile-menu" onClick={() => setMobileNav(!mobileNav)} aria-label="Toggle menu">{mobileNav ? <X /> : <Menu />}</button><div className="pb-breadcrumb">Godrej Nest Premier League <span>/</span> <b>{tab}</b></div><div className="pb-top-actions"><div className="pb-sync"><i /> All changes saved</div><button className="pb-icon-button" aria-label="Notifications" onClick={() => announce('You’re all caught up.')}><Bell size={18} /><i /></button><span className="pb-top-avatar">TS</span><button className="pb-logout" title="Sign out" onClick={() => onLogout ? onLogout() : (setSignedIn(false), window.history.replaceState({}, '', '/login'))}><LogOut size={17} /></button></div></header>
      <div className="pb-content"><div className="pb-page-heading"><div><div className="pb-kicker">WEDNESDAY, 19 NOVEMBER 2026 <span className="pb-heading-dot">·</span> SEASON 01</div><h1>{tab === 'Overview' ? 'Good afternoon, The Still Story' : tab}</h1><p>{tab === 'Overview' ? 'Here’s what’s happening with your tournament today.' : `Manage ${tab.toLowerCase()} for Godrej Nest Premier League.`}</p></div><div className="pb-heading-actions"><button className="pb-secondary" onClick={() => announce('Your public tournament link has been copied.')}>Share tournament <ArrowRight size={15} /></button><button className="pb-primary" onClick={() => setShowNewTournament(true)}><Plus size={17} /> New tournament</button></div></div>
      <section className="pb-tournament-banner"><div className="pb-banner-emblem"><span>GN</span><small>2026</small></div><div className="pb-banner-copy"><div><span className="pb-status-pill"><i /> AUCTION IN PROGRESS</span><span className="pb-demo-tag">DEMO</span></div><h2>Godrej Nest Premier League</h2><p><span>India</span><i /> 12 teams <i /> 48 players <i /> Created 12 Nov, 2026</p></div><button className="pb-banner-menu" onClick={() => setTab('Settings')} aria-label="Tournament settings"><MoreHorizontal /></button><div className="pb-banner-score"><small>AUCTION STATUS</small><strong><i /> LIVE NOW</strong><span><Clock3 size={13} /> Round 2 of 4</span></div></section>
      {tab === 'Overview' ? <>
        <div className="pb-section-label">TOURNAMENT OVERVIEW <span>LIVE UPDATES <i /></span></div><section className="pb-stat-grid"><div className="pb-stat-card"><div className="pb-stat-top"><span>PLAYERS</span><UserRound size={16} /></div><strong>{players.length + 42}</strong><small><span className="pb-stat-up">↑ 8</span> added this week</small><div className="pb-sparkline"><i style={{height:'35%'}}/><i style={{height:'50%'}}/><i style={{height:'43%'}}/><i style={{height:'67%'}}/><i style={{height:'54%'}}/><i style={{height:'82%'}}/><i style={{height:'72%'}}/><i style={{height:'100%'}}/></div></div><div className="pb-stat-card"><div className="pb-stat-top"><span>PLAYERS SOLD</span><Wallet size={16} /></div><strong>{sold}<small className="pb-stat-total"> / {players.length + 42}</small></strong><small><span className="pb-stat-up">{Math.round((sold/(players.length + 42))*100)}%</span> of player pool</small><div className="pb-progress"><i style={{width:`${Math.max(8,(sold/(players.length+42))*100)}%`}} /></div></div><div className="pb-stat-card"><div className="pb-stat-top"><span>TEAMS</span><Users size={16} /></div><strong>{teams.length}<small className="pb-stat-total"> / 12</small></strong><small><span className="pb-stat-up">4 active</span> in this round</small><div className="pb-mini-avatars">{teams.map(t=><i key={t.short} style={{'--team':t.color}}>{t.short}</i>)}<b>+8</b></div></div><div className="pb-stat-card"><div className="pb-stat-top"><span>TOTAL SPENT</span><Activity size={16} /></div><strong>₹2.4<small className="pb-stat-total">L</small></strong><small>Across all participating teams</small><div className="pb-spend-bars"><i/><i/><i/><i/><i/><i/><i/><i/><i/></div></div></section>
        <section className="pb-dashboard-grid"><div className="pb-panel pb-auction-panel"><div className="pb-panel-head"><div><div className="pb-panel-title">Live auction <span className="pb-live-chip"><i /> LIVE</span></div><p>Real-time bidding room</p></div><button className="pb-view-link" onClick={() => setTab('Live auction')}>Open auction room <ArrowRight size={14} /></button></div><div className="pb-player-live"><div className="pb-live-player-photo"><div className="pb-player-monogram">AR</div><span>#{String(145).padStart(3,'0')}</span></div><div className="pb-live-player-info"><div className="pb-role-tag">ALL-ROUNDER <i /> CATEGORY A</div><h3>Arjun Rao</h3><p>Right-hand bat <i /> Right-arm medium</p><div className="pb-player-details"><span>BASE PRICE <b>{money(25000)}</b></span><span>LOTS <b>145 / 180</b></span></div></div><div className="pb-live-time"><small>TIME LEFT</small><b>00:22</b><span><i /> AUTO-EXTEND ON</span></div></div><div className="pb-bid-activity"><div className="pb-bid-heading"><span>LEADING BID</span><span>LIVE BID FEED <i /></span></div><div className="pb-leading-bid"><span className="pb-team-avatar" style={{'--team':'#f26b52'}}>MS</span><div><b>Mumbai Strikers</b><small>Leading team</small></div><strong>{money(players[0].bid)}</strong></div><div className="pb-bid-track"><span>Mumbai Strikers</span><span>5 bids</span><b>Just now</b></div></div><div className="pb-auction-actions"><button className="pb-unsold-btn" onClick={() => decideLot('Unsold')}>Mark unsold</button><button className="pb-sold-btn" onClick={() => decideLot('Sold')}>Sold to Mumbai Strikers <ArrowRight size={15} /></button><button className="pb-add-bid" onClick={bid}><Plus size={16} /> {money(players[0].bid + 5000)}</button></div></div>
          <div className="pb-panel pb-teams-panel"><div className="pb-panel-head"><div><div className="pb-panel-title">Team purses</div><p>Balance across 12 teams</p></div><button className="pb-icon-link" onClick={() => setTab('Teams')}><ArrowRight size={16} /></button></div><div className="pb-purse-list">{teams.map((team,i)=><div className="pb-purse-row" key={team.short}><span className="pb-team-avatar" style={{'--team':team.color}}>{team.short}</span><div className="pb-purse-name"><b>{team.name}</b><small>{team.players} players <i /> {i+3} bids won</small></div><div className="pb-purse-right"><b>{money(Math.max(0,settings.teamPurse-squad.filter(player=>['Sold','Retained'].includes(player.status)).reduce((total,player)=>total+Number(player.soldPrice||player.basePrice||0),0)))}</b><small>of ₹10L</small></div><div className="pb-purse-bar"><i style={{width:`${100-team.purse/10000}%`,background:team.color}} /></div></div>)}</div><button className="pb-all-teams" onClick={() => setTab('Teams')}>View all teams <ArrowRight size={14} /></button></div></section>
        <section className="pb-panel pb-players-panel"><div className="pb-panel-head"><div><div className="pb-panel-title">Recent players <span className="pb-count-badge">48</span></div><p>Players in the auction pool</p></div><div className="pb-player-toolbar"><label className="pb-search"><Search size={15} /><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search players" /></label><button className="pb-secondary pb-filter-btn" onClick={() => announce('Showing all player categories.')}>All categories <ChevronDown size={14} /></button><button className="pb-icon-link" onClick={() => setTab('Players')}><ArrowRight size={16} /></button></div></div><div className="pb-table-wrap"><table className="pb-table"><thead><tr><th>PLAYER</th><th>ROLE</th><th>CATEGORY</th><th>BASE PRICE</th><th>STATUS</th><th>TEAM</th><th /></tr></thead><tbody>{filteredPlayers.slice(0,5).map(p=><tr key={p.name}><td><div className="pb-player-cell"><span className="pb-player-thumb" style={{'--portrait':p.color}}>{p.initials}</span><b>{p.name}</b></div></td><td>{p.role}</td><td><span className="pb-grade">{p.category}</span></td><td>{money(p.base)}</td><td><span className={`pb-player-status ${p.status.toLowerCase().replace(' ','-')}`}><i />{p.status}</span></td><td>{p.team || '—'}</td><td><button className="pb-row-menu" onClick={() => announce(`${p.name} · ${p.status}`)}><MoreHorizontal size={16} /></button></td></tr>)}</tbody></table></div><button className="pb-table-footer" onClick={() => setTab('Players')}>View all 48 players <ArrowRight size={14} /></button></section>
        <footer className="pb-footer"><span><span className="pb-footer-mark"><Command size={13}/></span> PlayBid <i /> Your tournament, your game.</span><span><i className="pb-footer-connected" /> Real-time sync active <span className="pb-footer-version">v2.8.1</span></span></footer>
      </> : <section className="pb-panel pb-standalone"><div className="pb-panel-head"><div><div className="pb-panel-title">{tab === 'Live auction' ? 'Auction control room' : tab}<span className="pb-live-chip"><i /> LIVE</span></div><p>{tab === 'Live auction' ? 'Manage player lots and bidding activity.' : `Tournament ${tab.toLowerCase()} overview.`}</p></div><button className="pb-primary" onClick={() => tab === 'Players' ? announce('Add player form is ready for your next step.') : tab === 'Teams' ? announce('Add team form is ready for your next step.') : setTab('Overview')}><Plus size={16}/> {tab === 'Players' ? 'Add player' : tab === 'Teams' ? 'Add team' : 'Back to overview'}</button></div><div className="pb-table-wrap"><table className="pb-table"><thead><tr><th>PLAYER</th><th>ROLE</th><th>CATEGORY</th><th>BASE PRICE</th><th>STATUS</th><th>TEAM</th><th /></tr></thead><tbody>{filteredPlayers.map(p=><tr key={p.name}><td><div className="pb-player-cell"><span className="pb-player-thumb" style={{'--portrait':p.color}}>{p.initials}</span><b>{p.name}</b></div></td><td>{p.role}</td><td><span className="pb-grade">{p.category}</span></td><td>{money(p.base)}</td><td><span className={`pb-player-status ${p.status.toLowerCase().replace(' ','-')}`}><i />{p.status}</span></td><td>{p.team || '—'}</td><td><button className="pb-row-menu" onClick={() => announce(`${p.name} · ${p.status}`)}><MoreHorizontal size={16}/></button></td></tr>)}</tbody></table></div></section>}
      </div>
    </main>
    {showNewTournament && <div className="pb-modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setShowNewTournament(false)}><form className="pb-new-modal" onSubmit={e=>{e.preventDefault();setShowNewTournament(false);announce('Tournament draft created in this preview.')}}><button type="button" className="pb-modal-x" onClick={()=>setShowNewTournament(false)}><X size={18}/></button><div className="pb-kicker">GET STARTED</div><h2>Create a tournament</h2><p>Set up your league workspace and invite your teams.</p><label>Tournament name<input required placeholder="e.g. Summer Premier League" /></label><label>Location<input placeholder="City, country" /></label><label>Number of teams<select defaultValue="8"><option>4</option><option>8</option><option>12</option><option>16</option><option>32</option></select></label><button className="pb-primary">Create tournament <ArrowRight size={16}/></button></form></div>}
    {notice && <div className="pb-toast">{notice}</div>}
  </div>;
}
